export const npc={x:12,y:12,name:'Ilyra',role:'Guardiã do farol'};
export const portal={x:28,y:9};
const seeded=n=>{const v=Math.sin(n*127.1+311.7)*43758.5453;return v-Math.floor(v)};
export function terrain(x,y,zone){if(zone==='dungeon')return x<3||y<3||x>32||y>32?'void':'stone';if(x<0||y<0||x>42||y>42)return 'water';const shore=33+Math.sin(y*.23)*2.6;if(x>shore)return 'water';if(x>shore-2)return 'sand';return Math.abs(y-(18+Math.sin(x*.15)*2))<1.3||Math.abs(x-12)<1.1&&y<19?'path':'grass';}
